INSERT INTO production_examples (id, titre, resume, contenu, audio_url, plan_points, niveau_indicatif, display_order, created_at, task_id, audio_status, audio_voice, audio_duration_sec, audio_generated_at, audio_batch_id, audio_error, explications, ssml_text) VALUES ('d93baad0-2bef-4f71-a729-ab8e08c015da','Entretien dirigé : un cuisinier se présente','Un échange réaliste d''environ 3 minutes : le candidat se présente et l''examinateur relance avec des questions ouvertes.','[Examinateur] Bonjour. Pour commencer cette première partie, est-ce que vous pouvez vous présenter, s''il vous plaît ?
[Candidat] Bonjour. Oui, avec plaisir. Je m''appelle Samuel, j''ai 34 ans et je suis camerounais. Je suis né à Douala, mais j''habite à Nantes depuis maintenant cinq ans.
[Examinateur] Très bien. Et qu''est-ce que vous faites dans la vie ?
[Candidat] Je suis cuisinier dans un restaurant du centre-ville. Au début, j''ai commencé comme simple commis de cuisine, et petit à petit, grâce à mon travail, je suis devenu chef de partie. J''aime beaucoup ce métier, parce qu''il est créatif et qu''on ne s''ennuie jamais. Chaque jour est différent.
[Examinateur] C''est intéressant. Et qu''est-ce qui vous a amené en France, au départ ?
[Candidat] À l''origine, je suis venu pour faire des études en gestion à l''université. Pendant ces années, j''ai rencontré ma compagne, qui est française. Nous nous sommes installés ensemble à Nantes, et aujourd''hui, nous avons une petite fille de deux ans. C''est pour cela que j''ai décidé de construire ma vie ici.
[Examinateur] Je comprends. Parlez-moi un peu de vos loisirs. Comment occupez-vous votre temps libre ?
[Candidat] J''ai deux grandes passions. La première, c''est le football : je joue tous les dimanches matin avec une équipe d''amis, c''est un vrai moment de détente. La deuxième, évidemment, c''est la cuisine. Même à la maison, j''aime tester de nouvelles recettes et faire découvrir à ma famille les plats traditionnels de mon pays.
[Examinateur] Et si vous pensez à l''avenir, quels sont vos projets ?
[Candidat] Mon plus grand rêve, c''est d''ouvrir mon propre restaurant. J''aimerais proposer une cuisine originale, qui mélange les saveurs françaises et africaines. Je pense qu''il y a vraiment quelque chose de beau à faire avec ce mélange de cultures. C''est aussi pour cette raison que je passe le TCF aujourd''hui : je prépare une demande de naturalisation, car je me sens désormais chez moi en France.
[Examinateur] Eh bien, je vous remercie. C''était une présentation très claire et complète.
[Candidat] Merci à vous.','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/3d1e3679-209b-4733-9c6b-9ee9a1a66b32.mp3','["Examinateur : invitation à se présenter", "Identité (nom, âge, origine, ville)", "Travail + parcours développé (commis -> chef)", "Venue en France + situation familiale", "Loisirs détaillés (football, cuisine)", "Projets + lien avec le TCF et la naturalisation", "Clôture"]','B1','0','2026-05-31 14:11:17.047759+02','2d1bea33-2ba8-4524-948c-89595c55fea6','PUBLISHED','fr-FR-DeniseNeural','132','2026-05-31 14:11:32.972796+02','60638f5e-6593-4c15-b0cb-de26ec371934',NULL,'Ce modèle montre un entretien réussi : le candidat ne récite pas un texte appris par cœur, il répond précisément à chaque question et développe avec des détails concrets. Remarquez : (1) il varie les temps (présent pour le quotidien, passé composé pour le parcours) ; (2) il donne des exemples vivants ("commis → chef de partie", "football le dimanche") au lieu de généralités ; (3) il relie naturellement sa motivation au TCF à la fin. À l''examen, l''examinateur vous relancera : ne répondez jamais par un seul mot, enrichissez chaque réponse avec une raison ou un exemple. C''est le candidat qui doit parler le plus.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Bonjour. Pour commencer cette première partie, est-ce que vous pouvez vous présenter, s''il vous plaît ?</prosody><break time="700ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Bonjour. Oui, avec plaisir. Je m''appelle Samuel, j''ai 34 ans et je suis camerounais. Je suis né à Douala, mais j''habite à Nantes depuis maintenant cinq ans.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Très bien. Et qu''est-ce que vous faites dans la vie ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Je suis cuisinier dans un restaurant du centre-ville. Au début, j''ai commencé comme simple commis de cuisine, et petit à petit, grâce à mon travail, je suis devenu chef de partie. J''aime beaucoup ce métier, parce qu''il est créatif et qu''on ne s''ennuie jamais. Chaque jour est différent.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">C''est intéressant. Et qu''est-ce qui vous a amené en France, au départ ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">À l''origine, je suis venu pour faire des études en gestion à l''université. Pendant ces années, j''ai rencontré ma compagne, qui est française. Nous nous sommes installés ensemble à Nantes, et aujourd''hui, nous avons une petite fille de deux ans. C''est pour cela que j''ai décidé de construire ma vie ici.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Je comprends. Parlez-moi un peu de vos loisirs. Comment occupez-vous votre temps libre ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">J''ai deux grandes passions. La première, c''est le football : je joue tous les dimanches matin avec une équipe d''amis, c''est un vrai moment de détente. La deuxième, évidemment, c''est la cuisine. Même à la maison, j''aime tester de nouvelles recettes et faire découvrir à ma famille les plats traditionnels de mon pays.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Et si vous pensez à l''avenir, quels sont vos projets ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Mon plus grand rêve, c''est d''ouvrir mon propre restaurant. J''aimerais proposer une cuisine originale, qui mélange les saveurs françaises et africaines. Je pense qu''il y a vraiment quelque chose de beau à faire avec ce mélange de cultures. C''est aussi pour cette raison que je passe le TCF aujourd''hui : je prépare une demande de naturalisation, car je me sens désormais chez moi en France.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Eh bien, je vous remercie. C''était une présentation très claire et complète.</prosody><break time="500ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Merci à vous.</prosody></voice></speak>');
INSERT INTO production_examples (id, titre, resume, contenu, audio_url, plan_points, niveau_indicatif, display_order, created_at, task_id, audio_status, audio_voice, audio_duration_sec, audio_generated_at, audio_batch_id, audio_error, explications, ssml_text) VALUES ('8426b25d-993a-400b-8efd-be38dd34d51a','Entretien dirigé : une assistante administrative se présente','Un échange réaliste : présentation personnelle plus longue, parcours, famille, quotidien, loisirs et projets.','[Examinateur] Bonjour. Pour commencer, pouvez-vous vous présenter de façon assez complète, s''il vous plaît ?
[Candidat] Bonjour. Oui, bien sûr. Je m''appelle Aïcha Benali, j''ai 38 ans et je suis marocaine. Je suis née à Rabat, dans une famille assez nombreuse, avec deux frères et une sœur. Aujourd''hui, j''habite à Rennes, en Bretagne, avec mon mari et nos deux enfants. Mon fils a neuf ans et ma fille a six ans. Je vis en France depuis presque sept ans, et petit à petit, j''ai construit ici ma vie personnelle et professionnelle.
[Examinateur] Très bien. Pouvez-vous parler un peu plus de votre parcours ?
[Candidat] Au Maroc, j''ai étudié la comptabilité et j''ai travaillé pendant plusieurs années dans une petite entreprise familiale. Quand je suis arrivée en France, au début, ce n''était pas facile, parce que je ne connaissais pas bien les démarches administratives et je devais aussi améliorer mon français. J''ai suivi des cours, puis j''ai fait une formation courte d''assistante administrative. Aujourd''hui, je travaille dans une association qui accompagne des personnes âgées. Je m''occupe de l''accueil, des rendez-vous et parfois des dossiers. J''aime beaucoup ce travail, parce que je me sens utile.
[Examinateur] Et comment se passe votre vie quotidienne ?
[Candidat] Ma vie quotidienne est bien organisée. Le matin, je prépare les enfants pour l''école, ensuite je vais au travail en bus. Je travaille généralement de neuf heures à dix-sept heures. Le soir, je récupère les enfants, je prépare le dîner et j''aide mon fils à faire ses devoirs. Le week-end, nous aimons sortir au parc, voir des amis ou visiter les environs. Rennes est une ville agréable, pas trop grande, et je trouve les gens assez accueillants.
[Examinateur] Qu''aimez-vous faire pendant votre temps libre ?
[Candidat] Quand j''ai un peu de temps pour moi, j''aime marcher, lire des romans simples en français et cuisiner. La cuisine est très importante pour moi, parce qu''elle me permet de garder un lien avec mon pays. Par exemple, je prépare souvent du couscous ou des tajines quand nous invitons des amis. J''aime aussi découvrir des plats français, comme les crêpes ou les gratins.
[Examinateur] Et quels sont vos projets pour l''avenir ?
[Candidat] Mon premier projet, c''est de continuer à progresser en français, surtout à l''oral, pour être plus à l''aise dans mon travail. Ensuite, j''aimerais obtenir un poste plus stable dans l''administration ou dans une mairie, parce que j''aime le contact avec le public. Enfin, je souhaite demander la nationalité française. Mes enfants grandissent ici, mon mari travaille ici, et moi aussi je me sens de plus en plus chez moi en France. C''est pour cela que je prépare sérieusement le TCF.
[Examinateur] Merci, votre présentation était complète.
[Candidat] Merci beaucoup.','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/e32aeed4-c1a2-48df-9e56-608ab6b384f8.mp3','["Présentation longue : identité, origine, famille, ville", "Parcours dans le pays d''origine", "Arrivée en France + difficultés", "Formation et travail actuel", "Vie quotidienne", "Loisirs", "Projets + lien avec le TCF"]','B1','1','2026-05-31 14:23:29.06096+02','2d1bea33-2ba8-4524-948c-89595c55fea6','PUBLISHED','fr-FR-HenriNeural','172','2026-05-31 14:23:56.259848+02','1102bbf8-7581-4ba8-8972-23c41289eac0',NULL,'Ce modèle développe davantage la première réponse de la tâche 1 : identité, origine, famille, ville actuelle, durée de vie en France. C''est mieux qu''une présentation trop courte. Le candidat parle ensuite de son parcours, de son travail, de sa vie quotidienne, de ses loisirs et de ses projets. Le style reste naturel, avec des phrases simples mais complètes.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Bonjour. Pour commencer, pouvez-vous vous présenter de façon assez complète, s''il vous plaît ?</prosody><break time="700ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Bonjour. Oui, bien sûr. Je m''appelle Aïcha Benali, j''ai 38 ans et je suis marocaine. Je suis née à Rabat, dans une famille assez nombreuse, avec deux frères et une sœur. Aujourd''hui, j''habite à Rennes, en Bretagne, avec mon mari et nos deux enfants. Mon fils a neuf ans et ma fille a six ans. Je vis en France depuis presque sept ans, et petit à petit, j''ai construit ici ma vie personnelle et professionnelle.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Très bien. Pouvez-vous parler un peu plus de votre parcours ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Au Maroc, j''ai étudié la comptabilité et j''ai travaillé pendant plusieurs années dans une petite entreprise familiale. Quand je suis arrivée en France, au début, ce n''était pas facile, parce que je ne connaissais pas bien les démarches administratives et je devais aussi améliorer mon français. J''ai suivi des cours, puis j''ai fait une formation courte d''assistante administrative. Aujourd''hui, je travaille dans une association qui accompagne des personnes âgées. Je m''occupe de l''accueil, des rendez-vous et parfois des dossiers. J''aime beaucoup ce travail, parce que je me sens utile.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Et comment se passe votre vie quotidienne ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Ma vie quotidienne est bien organisée. Le matin, je prépare les enfants pour l''école, ensuite je vais au travail en bus. Je travaille généralement de neuf heures à dix-sept heures. Le soir, je récupère les enfants, je prépare le dîner et j''aide mon fils à faire ses devoirs. Le week-end, nous aimons sortir au parc, voir des amis ou visiter les environs. Rennes est une ville agréable, pas trop grande, et je trouve les gens assez accueillants.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Qu''aimez-vous faire pendant votre temps libre ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Quand j''ai un peu de temps pour moi, j''aime marcher, lire des romans simples en français et cuisiner. La cuisine est très importante pour moi, parce qu''elle me permet de garder un lien avec mon pays. Par exemple, je prépare souvent du couscous ou des tajines quand nous invitons des amis. J''aime aussi découvrir des plats français, comme les crêpes ou les gratins.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Et quels sont vos projets pour l''avenir ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Mon premier projet, c''est de continuer à progresser en français, surtout à l''oral, pour être plus à l''aise dans mon travail. Ensuite, j''aimerais obtenir un poste plus stable dans l''administration ou dans une mairie, parce que j''aime le contact avec le public. Enfin, je souhaite demander la nationalité française. Mes enfants grandissent ici, mon mari travaille ici, et moi aussi je me sens de plus en plus chez moi en France. C''est pour cela que je prépare sérieusement le TCF.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Merci, votre présentation était complète.</prosody><break time="500ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Merci beaucoup.</prosody></voice></speak>');
INSERT INTO production_examples (id, titre, resume, contenu, audio_url, plan_points, niveau_indicatif, display_order, created_at, task_id, audio_status, audio_voice, audio_duration_sec, audio_generated_at, audio_batch_id, audio_error, explications, ssml_text) VALUES ('7852db89-cfa8-47ce-a6b6-e2e4d21e37aa','Entretien dirigé : un chauffeur-livreur se présente','Un échange réaliste avec une présentation longue : identité, famille, arrivée en France, travail, quotidien, loisirs et projets.','[Examinateur] Bonjour. Pour commencer, pouvez-vous vous présenter de manière assez complète, s''il vous plaît ?
[Candidat] Bonjour Madame. Oui, bien sûr. Je m''appelle Mamadou Diarra, j''ai 42 ans et je suis malien. Je suis né à Bamako, où j''ai grandi avec mes parents, mes deux frères et ma petite sœur. Aujourd''hui, j''habite à Toulouse avec ma femme et nos trois enfants. Mon plus grand fils est au collège, ma fille est à l''école primaire et le dernier est encore petit. Je vis en France depuis huit ans. Au début, je suis venu pour travailler, mais maintenant ma vie est vraiment ici : ma famille, mon travail, mes amis et les projets de mes enfants sont en France.
[Examinateur] Merci. Pouvez-vous parler un peu de votre parcours professionnel ?
[Candidat] Dans mon pays, j''ai travaillé comme chauffeur-livreur pendant plusieurs années. J''aimais ce métier parce que je rencontrais beaucoup de personnes et je connaissais bien la ville. En arrivant en France, j''ai d''abord fait des petits emplois : manutention, nettoyage et aide dans un entrepôt. Ce n''était pas toujours simple, surtout à cause de la langue et des horaires. Ensuite, j''ai passé une formation courte en logistique, et aujourd''hui je travaille dans une entreprise de transport. Je prépare les commandes et parfois je conduis un petit véhicule pour livrer des colis.
[Examinateur] Comment se passe une journée normale pour vous ?
[Candidat] Ma journée commence tôt. Je me lève vers cinq heures trente, je prends un café, puis je pars au travail. Je commence souvent à sept heures. Le matin, il faut vérifier les commandes, charger les cartons et respecter les horaires de livraison. À midi, je mange avec mes collègues. L''après-midi, je termine les livraisons ou je range l''entrepôt. Le soir, je rentre à la maison, je passe du temps avec les enfants et je parle avec ma femme de notre journée. Quand je suis trop fatigué, je me repose un peu, mais j''essaie toujours d''aider à la maison.
[Examinateur] Qu''est-ce que vous aimez faire pendant votre temps libre ?
[Candidat] Le week-end, j''aime beaucoup jouer au football avec des amis. Même si je ne suis plus très jeune, ça me fait du bien de courir et de rire avec les autres. J''aime aussi regarder des matchs à la télévision avec mon fils. En famille, nous aimons nous promener au bord de la Garonne ou aller au marché. J''aime cuisiner des plats de chez moi, par exemple le riz au poulet, et inviter des amis à la maison.
[Examinateur] Et quels sont vos projets pour les prochaines années ?
[Candidat] Mon projet principal, c''est de stabiliser encore plus ma situation. J''aimerais obtenir un CDI plus solide ou évoluer vers un poste de responsable d''équipe, parce que j''ai de l''expérience et je connais bien le travail. Je veux aussi continuer à améliorer mon français, surtout pour mieux écrire les mails professionnels. Enfin, je prépare le TCF parce que je souhaite demander la nationalité française. Pour moi, c''est important : je respecte ce pays, mes enfants grandissent ici, et je veux participer pleinement à la vie française.
[Examinateur] Merci beaucoup, votre présentation est claire.
[Candidat] Merci Madame.','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/e7aaa1fe-0356-4c64-a57a-32cf5d8e1af5.mp3','["Présentation longue : identité, origine, famille, ville", "Arrivée en France et installation", "Parcours professionnel", "Journée quotidienne", "Loisirs et vie de famille", "Projets professionnels", "Projet de nationalité française"]','B1','2','2026-05-31 15:20:54.81697+02','2d1bea33-2ba8-4524-948c-89595c55fea6','PUBLISHED','fr-FR-DeniseNeural','189','2026-05-31 15:25:46.199113+02','aba33541-4597-4a18-891c-2e51536510f7',NULL,'Ce modèle propose une première réponse plus longue et plus naturelle. Le candidat ne donne pas seulement son nom : il parle de son origine, de sa famille, de sa ville actuelle, de son arrivée en France et de son installation. Ensuite, il développe son parcours professionnel, son quotidien, ses loisirs et ses projets. La voix SSML du candidat est masculine car Mamadou est un homme.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Bonjour. Pour commencer, pouvez-vous vous présenter de manière assez complète, s''il vous plaît ?</prosody><break time="700ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Bonjour Madame. Oui, bien sûr. Je m''appelle Mamadou Diarra, j''ai 42 ans et je suis malien. Je suis né à Bamako, où j''ai grandi avec mes parents, mes deux frères et ma petite sœur. Aujourd''hui, j''habite à Toulouse avec ma femme et nos trois enfants. Mon plus grand fils est au collège, ma fille est à l''école primaire et le dernier est encore petit. Je vis en France depuis huit ans. Au début, je suis venu pour travailler, mais maintenant ma vie est vraiment ici : ma famille, mon travail, mes amis et les projets de mes enfants sont en France.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Merci. Pouvez-vous parler un peu de votre parcours professionnel ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Dans mon pays, j''ai travaillé comme chauffeur-livreur pendant plusieurs années. J''aimais ce métier parce que je rencontrais beaucoup de personnes et je connaissais bien la ville. En arrivant en France, j''ai d''abord fait des petits emplois : manutention, nettoyage et aide dans un entrepôt. Ce n''était pas toujours simple, surtout à cause de la langue et des horaires. Ensuite, j''ai passé une formation courte en logistique, et aujourd''hui je travaille dans une entreprise de transport. Je prépare les commandes et parfois je conduis un petit véhicule pour livrer des colis.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Comment se passe une journée normale pour vous ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Ma journée commence tôt. Je me lève vers cinq heures trente, je prends un café, puis je pars au travail. Je commence souvent à sept heures. Le matin, il faut vérifier les commandes, charger les cartons et respecter les horaires de livraison. À midi, je mange avec mes collègues. L''après-midi, je termine les livraisons ou je range l''entrepôt. Le soir, je rentre à la maison, je passe du temps avec les enfants et je parle avec ma femme de notre journée. Quand je suis trop fatigué, je me repose un peu, mais j''essaie toujours d''aider à la maison.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Qu''est-ce que vous aimez faire pendant votre temps libre ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Le week-end, j''aime beaucoup jouer au football avec des amis. Même si je ne suis plus très jeune, ça me fait du bien de courir et de rire avec les autres. J''aime aussi regarder des matchs à la télévision avec mon fils. En famille, nous aimons nous promener au bord de la Garonne ou aller au marché. J''aime cuisiner des plats de chez moi, par exemple le riz au poulet, et inviter des amis à la maison.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Et quels sont vos projets pour les prochaines années ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Mon projet principal, c''est de stabiliser encore plus ma situation. J''aimerais obtenir un CDI plus solide ou évoluer vers un poste de responsable d''équipe, parce que j''ai de l''expérience et je connais bien le travail. Je veux aussi continuer à améliorer mon français, surtout pour mieux écrire les mails professionnels. Enfin, je prépare le TCF parce que je souhaite demander la nationalité française. Pour moi, c''est important : je respecte ce pays, mes enfants grandissent ici, et je veux participer pleinement à la vie française.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Merci beaucoup, votre présentation est claire.</prosody><break time="500ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Merci Madame.</prosody></voice></speak>');
INSERT INTO production_examples (id, titre, resume, contenu, audio_url, plan_points, niveau_indicatif, display_order, created_at, task_id, audio_status, audio_voice, audio_duration_sec, audio_generated_at, audio_batch_id, audio_error, explications, ssml_text) VALUES ('e66f625e-b599-458f-b689-388b1c5085f9','Donner son opinion : les transports en commun gratuits','Un monologue argumenté d''environ 3 min 30, structuré comme à l''examen : introduction, arguments, objection, conclusion.','[Candidat] Aujourd''hui, je voudrais parler de la question des transports en commun gratuits. C''est un sujet dont on entend beaucoup parler dans les grandes villes, et je trouve que c''est une idée vraiment intéressante, même si elle mérite réflexion. Je vais donc vous donner mon point de vue.

Pour commencer, je pense que rendre les transports gratuits aurait surtout des avantages. Le premier argument, c''est l''environnement. Si les bus et les trams sont gratuits, beaucoup de gens vont laisser leur voiture à la maison. Par conséquent, il y aura moins de pollution dans l''air et moins d''embouteillages aux heures de pointe. Par exemple, dans certaines villes qui ont déjà testé la gratuité, on a constaté que le nombre de voitures dans le centre avait nettement diminué en quelques mois seulement.

Le deuxième argument, c''est la justice sociale. Pour beaucoup de personnes, le prix des transports représente une vraie difficulté. Je pense notamment aux étudiants, aux personnes âgées ou aux familles qui ont de petits revenus. Grâce à la gratuité, tout le monde pourrait se déplacer librement, que ce soit pour aller travailler, pour étudier, ou simplement pour aller voir un médecin. C''est une question d''égalité entre les citoyens.

Bien sûr, on pourrait m''objecter que tout cela coûte très cher à la collectivité. Et c''est vrai, je le reconnais. Si personne ne paie son ticket, il faut bien que cet argent vienne de quelque part : en général, ce sont les impôts des habitants. Certaines personnes pensent aussi que la gratuité pourrait entraîner des dégradations ou un manque de respect du matériel.

Cependant, malgré ces objections, je reste convaincu que les bénéfices sont plus importants que les inconvénients. À condition que le réseau soit bien organisé et correctement financé, la gratuité peut vraiment améliorer la vie quotidienne des habitants et protéger l''environnement. Pour conclure, je dirais que je suis plutôt favorable à cette idée, mais qu''il faut la mettre en place progressivement, et l''adapter à la taille et aux moyens de chaque ville. Voilà, c''était mon opinion sur ce sujet.','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/65f4eb45-969b-46b6-b8ad-6f7d794df3d8.mp3','["Introduction : sujet + position", "Argument 1 (environnement) + exemple", "Argument 2 (justice sociale) + exemples", "Objection (coût, dégradations)", "Réponse à l''objection", "Conclusion nuancée (subjonctif) + adaptation par ville"]','B1','0','2026-05-31 14:11:17.047759+02','5e739a88-a418-49ad-a7f2-8266c899ad2a','PUBLISHED','fr-FR-DeniseNeural','118','2026-05-31 14:11:35.498484+02','60638f5e-6593-4c15-b0cb-de26ec371934',NULL,'Ce modèle suit exactement la structure attendue à la tâche 3 : (1) une introduction qui annonce le sujet et la position ; (2) deux arguments clairs, chacun illustré ("le premier argument... par exemple...", "le deuxième argument...") ; (3) une objection honnêtement présentée ("on pourrait m''objecter que...") ; (4) une réponse à cette objection ; (5) une conclusion nuancée. Remarquez les connecteurs logiques (pour commencer, par conséquent, cependant, à condition que + subjonctif, pour conclure) qui structurent tout le discours. Pour réussir, ne donnez pas seulement votre avis : justifiez-le avec des exemples et anticipez l''avis contraire.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Aujourd''hui, je voudrais parler de la question des transports en commun gratuits. C''est un sujet dont on entend beaucoup parler dans les grandes villes, et je trouve que c''est une idée vraiment intéressante, même si elle mérite réflexion. Je vais donc vous donner mon point de vue.<break time="600ms"/>Pour commencer, je pense que rendre les transports gratuits aurait surtout des avantages. Le premier argument, c''est l''environnement. Si les bus et les trams sont gratuits, beaucoup de gens vont laisser leur voiture à la maison. Par conséquent, il y aura moins de pollution dans l''air et moins d''embouteillages aux heures de pointe. Par exemple, dans certaines villes qui ont déjà testé la gratuité, on a constaté que le nombre de voitures dans le centre avait nettement diminué en quelques mois seulement.<break time="600ms"/>Le deuxième argument, c''est la justice sociale. Pour beaucoup de personnes, le prix des transports représente une vraie difficulté. Je pense notamment aux étudiants, aux personnes âgées ou aux familles qui ont de petits revenus. Grâce à la gratuité, tout le monde pourrait se déplacer librement, que ce soit pour aller travailler, pour étudier, ou simplement pour aller voir un médecin. C''est une question d''égalité entre les citoyens.<break time="600ms"/>Bien sûr, on pourrait m''objecter que tout cela coûte très cher à la collectivité. Et c''est vrai, je le reconnais. Si personne ne paie son ticket, il faut bien que cet argent vienne de quelque part : en général, ce sont les impôts des habitants. Certaines personnes pensent aussi que la gratuité pourrait entraîner des dégradations ou un manque de respect du matériel.<break time="600ms"/>Cependant, malgré ces objections, je reste convaincu que les bénéfices sont plus importants que les inconvénients. À condition que le réseau soit bien organisé et correctement financé, la gratuité peut vraiment améliorer la vie quotidienne des habitants et protéger l''environnement. Pour conclure, je dirais que je suis plutôt favorable à cette idée, mais qu''il faut la mettre en place progressivement, et l''adapter à la taille et aux moyens de chaque ville. Voilà, c''était mon opinion sur ce sujet.</prosody></voice></speak>');
INSERT INTO production_examples (id, titre, resume, contenu, audio_url, plan_points, niveau_indicatif, display_order, created_at, task_id, audio_status, audio_voice, audio_duration_sec, audio_generated_at, audio_batch_id, audio_error, explications, ssml_text) VALUES ('75a0001d-1f5c-43ac-a196-2fc7c3eddde8','Donner son opinion : le télétravail','Un monologue argumenté sur les avantages, les limites et l''équilibre nécessaire du télétravail.','[Candidat] Aujourd''hui, je vais parler du télétravail. Depuis quelques années, beaucoup de personnes travaillent parfois depuis leur domicile. À mon avis, le télétravail est une bonne chose, mais seulement s''il est bien organisé.

D''abord, le premier avantage, c''est le gain de temps. Quand on travaille à la maison, on évite les transports, les embouteillages et la fatigue du trajet. Par exemple, une personne qui passe une heure le matin et une heure le soir dans les transports gagne deux heures dans sa journée. Elle peut utiliser ce temps pour sa famille, pour faire du sport ou simplement pour se reposer.

Ensuite, le télétravail peut aider à mieux se concentrer. Dans certains bureaux, il y a beaucoup de bruit, des réunions, des collègues qui parlent ou qui interrompent. À la maison, si on a un endroit calme, on peut parfois travailler plus efficacement. Pour certains métiers administratifs ou informatiques, c''est vraiment pratique.

Mais il y a aussi des inconvénients. Le premier, c''est l''isolement. Quand on reste toujours chez soi, on voit moins ses collègues et on peut se sentir seul. Le deuxième problème, c''est la séparation entre la vie professionnelle et la vie personnelle. Certaines personnes continuent à répondre aux messages le soir ou pendant le week-end, parce que leur ordinateur est toujours à côté d''elles.

Je pense donc que la meilleure solution, c''est un équilibre. Par exemple, deux jours de télétravail par semaine et trois jours au bureau. Comme ça, on garde le contact avec l''équipe, mais on profite aussi des avantages du travail à distance. L''entreprise doit aussi fixer des règles claires : horaires, droit à la déconnexion, réunions nécessaires seulement.

Pour conclure, je suis plutôt favorable au télétravail, mais pas à cent pour cent. Il peut améliorer la qualité de vie des salariés, à condition de respecter un cadre clair et de ne pas couper les personnes de leurs collègues.','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/10f2fa20-2899-4bce-84a8-378c9e8c8ea2.mp3','["Introduction + position", "Argument 1 : gain de temps", "Argument 2 : concentration", "Limites : isolement et frontière vie privée", "Solution équilibrée", "Conclusion nuancée"]','B1','1','2026-05-31 14:23:29.06096+02','5e739a88-a418-49ad-a7f2-8266c899ad2a','PUBLISHED','fr-FR-HenriNeural','113','2026-05-31 14:24:01.449982+02','1102bbf8-7581-4ba8-8972-23c41289eac0',NULL,'Ce modèle convient à la tâche 3 : avis clair, deux arguments, limites, solution équilibrée et conclusion. Le style reste accessible, sans dissertation trop scolaire, mais avec des connecteurs utiles : d''abord, ensuite, mais, donc, pour conclure.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Aujourd''hui, je vais parler du télétravail. Depuis quelques années, beaucoup de personnes travaillent parfois depuis leur domicile. À mon avis, le télétravail est une bonne chose, mais seulement s''il est bien organisé.<break time="600ms"/>D''abord, le premier avantage, c''est le gain de temps. Quand on travaille à la maison, on évite les transports, les embouteillages et la fatigue du trajet. Par exemple, une personne qui passe une heure le matin et une heure le soir dans les transports gagne deux heures dans sa journée. Elle peut utiliser ce temps pour sa famille, pour faire du sport ou simplement pour se reposer.<break time="600ms"/>Ensuite, le télétravail peut aider à mieux se concentrer. Dans certains bureaux, il y a beaucoup de bruit, des réunions, des collègues qui parlent ou qui interrompent. À la maison, si on a un endroit calme, on peut parfois travailler plus efficacement. Pour certains métiers administratifs ou informatiques, c''est vraiment pratique.<break time="600ms"/>Mais il y a aussi des inconvénients. Le premier, c''est l''isolement. Quand on reste toujours chez soi, on voit moins ses collègues et on peut se sentir seul. Le deuxième problème, c''est la séparation entre la vie professionnelle et la vie personnelle. Certaines personnes continuent à répondre aux messages le soir ou pendant le week-end, parce que leur ordinateur est toujours à côté d''elles.<break time="600ms"/>Je pense donc que la meilleure solution, c''est un équilibre. Par exemple, deux jours de télétravail par semaine et trois jours au bureau. Comme ça, on garde le contact avec l''équipe, mais on profite aussi des avantages du travail à distance. L''entreprise doit aussi fixer des règles claires : horaires, droit à la déconnexion, réunions nécessaires seulement.<break time="600ms"/>Pour conclure, je suis plutôt favorable au télétravail, mais pas à cent pour cent. Il peut améliorer la qualité de vie des salariés, à condition de respecter un cadre clair et de ne pas couper les personnes de leurs collègues.</prosody></voice></speak>');
INSERT INTO production_examples (id, titre, resume, contenu, audio_url, plan_points, niveau_indicatif, display_order, created_at, task_id, audio_status, audio_voice, audio_duration_sec, audio_generated_at, audio_batch_id, audio_error, explications, ssml_text) VALUES ('bdcd4a0e-1c12-43f3-9a28-7238fc1fd905','Donner son opinion : le téléphone chez les enfants','Un monologue argumenté sur les avantages, les risques et les règles à mettre en place.','[Candidat] Aujourd''hui, je vais parler d''un sujet important : est-ce qu''il faut limiter l''utilisation du téléphone chez les enfants ? À mon avis, oui, il faut mettre des limites, mais il ne faut pas interdire complètement le téléphone.

D''abord, le téléphone peut être utile. Par exemple, un enfant peut appeler ses parents s''il a un problème, s''il sort de l''école ou s''il prend le bus. Il peut aussi utiliser certaines applications pour apprendre une langue, faire des exercices ou chercher une information simple. Donc, le téléphone n''est pas seulement un objet pour jouer.

Mais il y a aussi beaucoup de risques. Le premier risque, c''est le temps passé devant l''écran. Certains enfants regardent des vidéos pendant des heures, jouent trop longtemps ou dorment plus tard à cause du téléphone. Cela peut fatiguer les yeux, diminuer la concentration et créer des disputes à la maison.

Le deuxième risque concerne les réseaux sociaux et les contenus dangereux. Un enfant ne sait pas toujours reconnaître une fausse information, une publicité ou une personne mal intentionnée. Les parents doivent donc accompagner leurs enfants et expliquer les règles de sécurité.

Pour moi, la meilleure solution est de fixer un cadre clair. Par exemple, pas de téléphone pendant les repas, pas de téléphone dans la chambre la nuit, et un temps limité après les devoirs. Les parents doivent aussi montrer l''exemple, parce qu''un enfant comprend mieux les règles si les adultes les respectent aussi.

Pour conclure, je pense que le téléphone peut être utile pour les enfants, mais il doit rester contrôlé. Il faut apprendre aux enfants à l''utiliser correctement, avec des horaires, des règles et un vrai dialogue avec les parents.','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/4edc0ac9-9e8f-4ee6-b06f-370845e8ed38.mp3','["Introduction + avis", "Avantage : sécurité et apprentissage", "Risque : temps d’écran", "Risque : réseaux sociaux", "Solution : règles claires", "Rôle des parents", "Conclusion équilibrée"]','B1','2','2026-05-31 15:20:54.81697+02','5e739a88-a418-49ad-a7f2-8266c899ad2a','PUBLISHED','fr-FR-DeniseNeural','104','2026-05-31 15:25:51.516802+02','aba33541-4597-4a18-891c-2e51536510f7',NULL,'Ce modèle convient à la tâche 3 : il donne une opinion claire, nuance le sujet, présente des avantages, des risques et une solution équilibrée. Le style reste pratique et accessible pour le TCF IRN, avec des connecteurs simples. La voix SSML est féminine pour proposer aussi un modèle oral porté par une femme.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Aujourd''hui, je vais parler d''un sujet important : est-ce qu''il faut limiter l''utilisation du téléphone chez les enfants ? À mon avis, oui, il faut mettre des limites, mais il ne faut pas interdire complètement le téléphone.<break time="600ms"/>D''abord, le téléphone peut être utile. Par exemple, un enfant peut appeler ses parents s''il a un problème, s''il sort de l''école ou s''il prend le bus. Il peut aussi utiliser certaines applications pour apprendre une langue, faire des exercices ou chercher une information simple. Donc, le téléphone n''est pas seulement un objet pour jouer.<break time="600ms"/>Mais il y a aussi beaucoup de risques. Le premier risque, c''est le temps passé devant l''écran. Certains enfants regardent des vidéos pendant des heures, jouent trop longtemps ou dorment plus tard à cause du téléphone. Cela peut fatiguer les yeux, diminuer la concentration et créer des disputes à la maison.<break time="600ms"/>Le deuxième risque concerne les réseaux sociaux et les contenus dangereux. Un enfant ne sait pas toujours reconnaître une fausse information, une publicité ou une personne mal intentionnée. Les parents doivent donc accompagner leurs enfants et expliquer les règles de sécurité.<break time="600ms"/>Pour moi, la meilleure solution est de fixer un cadre clair. Par exemple, pas de téléphone pendant les repas, pas de téléphone dans la chambre la nuit, et un temps limité après les devoirs. Les parents doivent aussi montrer l''exemple, parce qu''un enfant comprend mieux les règles si les adultes les respectent aussi.<break time="600ms"/>Pour conclure, je pense que le téléphone peut être utile pour les enfants, mais il doit rester contrôlé. Il faut apprendre aux enfants à l''utiliser correctement, avec des horaires, des règles et un vrai dialogue avec les parents.</prosody></voice></speak>');
INSERT INTO production_examples (id, titre, resume, contenu, audio_url, plan_points, niveau_indicatif, display_order, created_at, task_id, audio_status, audio_voice, audio_duration_sec, audio_generated_at, audio_batch_id, audio_error, explications, ssml_text) VALUES ('673f1495-0ef7-4418-a132-b2d5e165e953','Jeu de rôle : louer un appartement','Une interaction réaliste d''environ 3 min 30 : le candidat appelle une agence, échange avec l''agent et fixe une visite.','[Agent] Agence Belle Vue, bonjour, que puis-je faire pour vous ?
[Candidat] Bonjour Madame. Je vous appelle au sujet de l''appartement deux-pièces que j''ai vu sur votre annonce, dans le quartier des Halles. Est-ce qu''il est toujours disponible ?
[Agent] Oui, il est encore libre. C''est un 45 mètres carrés dans un quartier calme, au troisième étage avec ascenseur.
[Candidat] Ah, très bien, l''ascenseur c''est pratique. Pouvez-vous me dire quel est le montant du loyer, et si les charges sont comprises dedans ?
[Agent] Le loyer est de 780 euros par mois. Les charges sont en plus, elles s''élèvent à environ 50 euros, ce qui comprend l''eau et l''entretien des parties communes.
[Candidat] D''accord, je note. Et est-ce que l''appartement est meublé, ou est-ce qu''il faut que j''apporte mes propres meubles ?
[Agent] Il est loué vide, donc il faudra prévoir vos meubles. En revanche, la cuisine est entièrement équipée.
[Candidat] Parfait. Et le quartier, est-il bien desservi par les transports en commun ? C''est important pour moi car je travaille à l''autre bout de la ville.
[Agent] Oui, tout à fait. Il y a un arrêt de bus juste devant l''immeuble, et la station de tramway est à cinq minutes à pied seulement.
[Candidat] Très bien, ça me convient. Quels documents est-ce qu''il faut préparer pour constituer le dossier ?
[Agent] Il me faut une pièce d''identité, vos trois derniers bulletins de salaire, votre contrat de travail et votre dernier avis d''imposition.
[Candidat] D''accord, j''ai tous ces documents. Est-ce qu''il serait possible de visiter l''appartement cette semaine ?
[Agent] Bien sûr. Seriez-vous disponible samedi matin, vers dix heures ?
[Candidat] Samedi à dix heures, c''est parfait pour moi. Pouvez-vous me donner l''adresse exacte ?
[Agent] Oui, c''est au 12 rue des Halles. Je vous attendrai devant l''entrée.
[Candidat] Très bien, je vous remercie beaucoup pour toutes ces informations. À samedi, alors.
[Agent] Je vous en prie. À samedi, bonne journée !
[Candidat] Bonne journée à vous aussi, au revoir.','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/2dde8c14-61f3-4a01-ba5f-d934b4c6e589.mp3','["Agent ouvre l''échange", "Objet de l''appel + disponibilité", "Loyer + charges détaillées", "Meublé ou vide + cuisine", "Transports + réaction personnelle", "Documents du dossier", "Demande de visite + créneau + adresse", "Clôture polie"]','B1','0','2026-05-31 14:11:17.047759+02','aafce71c-0b12-4945-8a28-02f5d0f2299f','PUBLISHED','fr-FR-DeniseNeural','135','2026-05-31 14:11:34.542267+02','60638f5e-6593-4c15-b0cb-de26ec371934',NULL,'Ce modèle illustre une interaction complète et fluide. Points à imiter : (1) le candidat ouvre poliment et explique tout de suite la raison de son appel ; (2) il pose des questions variées et utiles (prix, charges, meublé ou non, transports, documents, visite) au lieu d''une seule ; (3) il réagit aux réponses ("l''ascenseur c''est pratique", "c''est important pour moi car...") plutôt que d''enchaîner mécaniquement ; (4) il conclut en fixant un rendez-vous concret et en demandant l''adresse. À l''examen, c''est l''examinateur qui joue l''agent : votre rôle est de mener l''échange et d''obtenir les informations, pas d''attendre passivement.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Agence Belle Vue, bonjour, que puis-je faire pour vous ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Bonjour Madame. Je vous appelle au sujet de l''appartement deux-pièces que j''ai vu sur votre annonce, dans le quartier des Halles. Est-ce qu''il est toujours disponible ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, il est encore libre. C''est un 45 mètres carrés dans un quartier calme, au troisième étage avec ascenseur.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Ah, très bien, l''ascenseur c''est pratique. Pouvez-vous me dire quel est le montant du loyer, et si les charges sont comprises dedans ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Le loyer est de 780 euros par mois. Les charges sont en plus, elles s''élèvent à environ 50 euros, ce qui comprend l''eau et l''entretien des parties communes.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">D''accord, je note. Et est-ce que l''appartement est meublé, ou est-ce qu''il faut que j''apporte mes propres meubles ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Il est loué vide, donc il faudra prévoir vos meubles. En revanche, la cuisine est entièrement équipée.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Parfait. Et le quartier, est-il bien desservi par les transports en commun ? C''est important pour moi car je travaille à l''autre bout de la ville.</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, tout à fait. Il y a un arrêt de bus juste devant l''immeuble, et la station de tramway est à cinq minutes à pied seulement.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Très bien, ça me convient. Quels documents est-ce qu''il faut préparer pour constituer le dossier ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Il me faut une pièce d''identité, vos trois derniers bulletins de salaire, votre contrat de travail et votre dernier avis d''imposition.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">D''accord, j''ai tous ces documents. Est-ce qu''il serait possible de visiter l''appartement cette semaine ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Bien sûr. Seriez-vous disponible samedi matin, vers dix heures ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Samedi à dix heures, c''est parfait pour moi. Pouvez-vous me donner l''adresse exacte ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, c''est au 12 rue des Halles. Je vous attendrai devant l''entrée.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Très bien, je vous remercie beaucoup pour toutes ces informations. À samedi, alors.</prosody><break time="500ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Je vous en prie. À samedi, bonne journée !</prosody><break time="500ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Bonne journée à vous aussi, au revoir.</prosody></voice></speak>');
INSERT INTO production_examples (id, titre, resume, contenu, audio_url, plan_points, niveau_indicatif, display_order, created_at, task_id, audio_status, audio_voice, audio_duration_sec, audio_generated_at, audio_batch_id, audio_error, explications, ssml_text) VALUES ('8c489a3f-d6f3-4650-af1d-32e2338deeb8','Jeu de rôle : s''inscrire à des cours de français','Le candidat appelle une association pour demander des informations et organiser un essai.','[Agent] Maison des associations, bonjour.
[Candidat] Bonjour Madame. Je vous appelle parce que j''ai vu une affiche pour des cours de français du soir. Je voudrais avoir quelques renseignements, s''il vous plaît.
[Agent] Bien sûr. Nous proposons plusieurs cours selon le niveau. Vous cherchez plutôt un cours débutant ou un cours intermédiaire ?
[Candidat] Je pense que j''ai déjà un niveau intermédiaire. Je comprends assez bien, mais je veux améliorer mon oral et préparer un examen de français.
[Agent] Dans ce cas, le groupe du mardi et du jeudi soir pourrait vous convenir. Les cours ont lieu de dix-huit heures trente à vingt heures.
[Candidat] D''accord. Est-ce que les cours sont toute l''année ou seulement pendant quelques semaines ?
[Agent] La session dure trois mois. Ensuite, les personnes peuvent se réinscrire si elles veulent continuer.
[Candidat] Très bien. Et combien coûte l''inscription pour les trois mois ?
[Agent] C''est trente euros pour l''année d''adhésion à l''association, puis quinze euros par mois pour les cours.
[Candidat] D''accord, ce n''est pas trop cher. Est-ce qu''il faut apporter des documents pour s''inscrire ?
[Agent] Oui, il faut une pièce d''identité, une photo et un justificatif de domicile.
[Candidat] Très bien, j''ai tout ça. Est-ce que je peux venir essayer un cours avant de m''inscrire définitivement ?
[Agent] Oui, c''est possible. Vous pouvez venir mardi prochain pour faire un essai gratuit.
[Candidat] Parfait. Et l''adresse exacte, c''est bien près de la mairie ?
[Agent] Oui, nous sommes au 8 rue Victor Hugo, juste derrière la mairie. L''entrée se fait par la petite porte bleue.
[Candidat] Merci. Une dernière question : est-ce que le professeur donne aussi des conseils pour le TCF ?
[Agent] Oui, pas à chaque cours, mais il y a souvent des exercices d''oral et de compréhension. Le professeur peut aussi vous orienter vers des ressources utiles.
[Candidat] Très bien, c''est exactement ce que je cherche. Je viendrai mardi prochain à dix-huit heures trente avec mes documents.
[Agent] Parfait, je note votre venue. Quel est votre nom ?
[Candidat] Je m''appelle Karim El Mansouri.
[Agent] Très bien Monsieur El Mansouri. À mardi.
[Candidat] Merci beaucoup, bonne journée.
[Agent] Bonne journée à vous.','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/c77d7436-b461-40c9-a0c2-70673ec29f4a.mp3','["Ouverture polie", "Objet de l''appel", "Niveau et besoin", "Horaires", "Durée et prix", "Documents", "Essai gratuit", "Adresse", "Confirmation finale"]','B1','1','2026-05-31 14:23:29.06096+02','aafce71c-0b12-4945-8a28-02f5d0f2299f','PUBLISHED','fr-FR-HenriNeural','150','2026-05-31 14:23:57.913686+02','1102bbf8-7581-4ba8-8972-23c41289eac0',NULL,'Ce modèle montre une bonne tâche 2 : le candidat mène l''échange, pose plusieurs questions utiles et vérifie les informations importantes. Il ne se contente pas de répondre ; il obtient le prix, les horaires, les documents, l''adresse et la possibilité d''un essai.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Maison des associations, bonjour.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Bonjour Madame. Je vous appelle parce que j''ai vu une affiche pour des cours de français du soir. Je voudrais avoir quelques renseignements, s''il vous plaît.</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Bien sûr. Nous proposons plusieurs cours selon le niveau. Vous cherchez plutôt un cours débutant ou un cours intermédiaire ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Je pense que j''ai déjà un niveau intermédiaire. Je comprends assez bien, mais je veux améliorer mon oral et préparer un examen de français.</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Dans ce cas, le groupe du mardi et du jeudi soir pourrait vous convenir. Les cours ont lieu de dix-huit heures trente à vingt heures.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">D''accord. Est-ce que les cours sont toute l''année ou seulement pendant quelques semaines ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">La session dure trois mois. Ensuite, les personnes peuvent se réinscrire si elles veulent continuer.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Très bien. Et combien coûte l''inscription pour les trois mois ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">C''est trente euros pour l''année d''adhésion à l''association, puis quinze euros par mois pour les cours.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">D''accord, ce n''est pas trop cher. Est-ce qu''il faut apporter des documents pour s''inscrire ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, il faut une pièce d''identité, une photo et un justificatif de domicile.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Très bien, j''ai tout ça. Est-ce que je peux venir essayer un cours avant de m''inscrire définitivement ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, c''est possible. Vous pouvez venir mardi prochain pour faire un essai gratuit.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Parfait. Et l''adresse exacte, c''est bien près de la mairie ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, nous sommes au 8 rue Victor Hugo, juste derrière la mairie. L''entrée se fait par la petite porte bleue.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Merci. Une dernière question : est-ce que le professeur donne aussi des conseils pour le TCF ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, pas à chaque cours, mais il y a souvent des exercices d''oral et de compréhension. Le professeur peut aussi vous orienter vers des ressources utiles.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Très bien, c''est exactement ce que je cherche. Je viendrai mardi prochain à dix-huit heures trente avec mes documents.</prosody><break time="500ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Parfait, je note votre venue. Quel est votre nom ?</prosody><break time="500ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Je m''appelle Karim El Mansouri.</prosody><break time="500ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Très bien Monsieur El Mansouri. À mardi.</prosody><break time="500ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Merci beaucoup, bonne journée.</prosody><break time="500ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Bonne journée à vous.</prosody></voice></speak>');
INSERT INTO production_examples (id, titre, resume, contenu, audio_url, plan_points, niveau_indicatif, display_order, created_at, task_id, audio_status, audio_voice, audio_duration_sec, audio_generated_at, audio_batch_id, audio_error, explications, ssml_text) VALUES ('6e2b2396-398a-48f1-974b-80f469ac717c','Jeu de rôle : inscrire son enfant à la natation','La candidate appelle le service des sports pour obtenir des informations et réserver une place.','[Agent] Service des sports de la mairie, bonjour.
[Candidat] Bonjour Monsieur. Je vous appelle parce que je voudrais inscrire ma fille à une activité sportive pendant l''année. Elle a dix ans et elle aimerait faire de la natation. Est-ce que vous pouvez me donner des informations, s''il vous plaît ?
[Agent] Oui, bien sûr. Nous avons des cours de natation pour les enfants le mercredi et le samedi. Votre fille sait déjà nager un peu ?
[Candidat] Oui, elle sait nager un peu, mais elle manque de confiance. Elle peut traverser une petite piscine, mais elle a encore peur dans le grand bassin.
[Agent] Dans ce cas, le groupe débutant avancé peut être adapté. Les enfants apprennent à mieux respirer, à flotter et à nager plus longtemps.
[Candidat] D''accord. Quels sont les horaires disponibles pour ce groupe ?
[Agent] Il y a un cours le mercredi à quinze heures et un autre le samedi à dix heures trente.
[Candidat] Le samedi m''intéresse, parce que je travaille le mercredi. Le cours dure combien de temps ?
[Agent] Le cours dure quarante-cinq minutes.
[Candidat] Très bien. Et combien coûte l''inscription pour l''année ?
[Agent] Pour les habitants de la commune, c''est cent vingt euros pour l''année. Pour les personnes qui habitent dans une autre ville, c''est cent cinquante euros.
[Candidat] Nous habitons dans la commune. Est-ce qu''il faut apporter un justificatif de domicile ?
[Agent] Oui, il faut une pièce d''identité du parent, un justificatif de domicile et un certificat médical pour l''enfant.
[Candidat] D''accord. Est-ce que je peux faire l''inscription en ligne ou je dois venir à la mairie ?
[Agent] Vous pouvez commencer le dossier en ligne, mais il faut ensuite venir déposer le certificat médical à l''accueil.
[Candidat] Très bien. Est-ce qu''il reste encore des places pour le samedi matin ?
[Agent] Oui, il reste trois places pour le moment.
[Candidat] Alors je préfère réserver une place si c''est possible. Ma fille s''appelle Inès Benyamina.
[Agent] Je peux noter son nom, mais la place sera confirmée seulement quand le dossier sera complet.
[Candidat] Je comprends. Je vais remplir le dossier aujourd''hui et passer demain à la mairie avec les documents.
[Agent] Très bien Madame. L''accueil est ouvert de neuf heures à dix-sept heures.
[Candidat] Merci beaucoup pour vos informations. Bonne journée Monsieur.
[Agent] Bonne journée Madame.','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/0825e31f-249f-4090-aca8-761442d6813f.mp3','["Ouverture polie", "Objet de l’appel", "Âge et niveau de l’enfant", "Horaires", "Durée du cours", "Tarif", "Documents nécessaires", "Inscription en ligne", "Réservation et confirmation"]','B1','2','2026-05-31 15:20:54.81697+02','aafce71c-0b12-4945-8a28-02f5d0f2299f','PUBLISHED','fr-FR-DeniseNeural','152','2026-05-31 15:25:47.981472+02','aba33541-4597-4a18-891c-2e51536510f7',NULL,'Ce modèle correspond bien à la tâche 2 : la candidate explique son besoin, pose des questions concrètes et confirme les informations utiles. Elle demande les horaires, le prix, les documents, la possibilité de réserver et la procédure d''inscription. La voix SSML de la candidate est féminine car la personne qui parle est une femme.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-HenriNeural"><prosody rate="0.95">Service des sports de la mairie, bonjour.</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Bonjour Monsieur. Je vous appelle parce que je voudrais inscrire ma fille à une activité sportive pendant l''année. Elle a dix ans et elle aimerait faire de la natation. Est-ce que vous pouvez me donner des informations, s''il vous plaît ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Oui, bien sûr. Nous avons des cours de natation pour les enfants le mercredi et le samedi. Votre fille sait déjà nager un peu ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, elle sait nager un peu, mais elle manque de confiance. Elle peut traverser une petite piscine, mais elle a encore peur dans le grand bassin.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Dans ce cas, le groupe débutant avancé peut être adapté. Les enfants apprennent à mieux respirer, à flotter et à nager plus longtemps.</pr